-- Summary Report by Month
SELECT 'November 2025' as Month, COUNT(*) as Bookings, CONCAT('₱', FORMAT(SUM(amount_paid), 2)) as Revenue FROM car_rentals WHERE booking_id LIKE 'CAR-202511%'
UNION ALL SELECT 'December 2025', COUNT(*), CONCAT('₱', FORMAT(SUM(amount_paid), 2)) FROM car_rentals WHERE booking_id LIKE 'CAR-202512%'
UNION ALL SELECT 'January 2026', COUNT(*), CONCAT('₱', FORMAT(SUM(amount_paid), 2)) FROM car_rentals WHERE booking_id LIKE 'CAR-202601%'
UNION ALL SELECT 'March 2026', COUNT(*), CONCAT('₱', FORMAT(SUM(amount_paid), 2)) FROM car_rentals WHERE booking_id LIKE 'CAR-202603%'
UNION ALL SELECT 'TOTAL', COUNT(*), CONCAT('₱', FORMAT(SUM(amount_paid), 2)) FROM car_rentals WHERE booking_id LIKE 'CAR-2025%' OR booking_id LIKE 'CAR-2026%';
